package com.prep.counting.domain;

import java.time.Instant;
import java.util.List;

/**
 * One request from a client: {@code POST /events}.
 *
 * @param batchId generated by the client and reused on every retry; it makes the event ids deterministic
 * @param ts      EVENT time: when the client recorded these items, not when the server received them
 */
public record EventBatch(String tenantId, String batchId, Instant ts, List<Item> items) {

    /** One key-value pair. The value is whatever JSON sent: Boolean, String, Number or null. */
    public record Item(String key, Object value) {}
}
